// Requirements:
// - Quantity should never become less than 1.
// - Increment should work correctly.
// - Decrement should work correctly.
// - Add a reset button that sets quantity to 1

// ===========================================
//          Code After Solved Bugs
// ===========================================
import { useState } from "react";
function Task3() {
  const [quantity, setQuantity] = useState(1);

  // ============================
  //     Increasing Qunatity
  // ============================
  function increaseQuantity() {
    setQuantity(quantity + 1);
  }

  // ============================
  //     Decreasing Qunatity
  // ============================
  function decreaseQuantity() {
    if (quantity > 1) {
      setQuantity(quantity - 1);
    }
    else if(quantity===1){
      setQuantity(1)
    }
  }

  // ============================
  //     Reset Qunatity
  // ============================
  function resetQuantity(){
    setQuantity(1)
  }
  return (
    <div>
      <h2>Quantity: {quantity}</h2>

      <button onClick={increaseQuantity}>+</button>
      <button onClick={decreaseQuantity}>-</button>
      <button onClick={resetQuantity}>Reset</button>
    </div>
  );
}

export default Task3;